using CrmSystem.Models.Entities;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace CrmSystem.Data.Configurations;

public class ClientConfiguration : IEntityTypeConfiguration<Client>
{
    public void Configure(EntityTypeBuilder<Client> b)
    {
        b.ToTable("Clients");
        b.HasKey(x => x.ClientId);

        // Generated by SQL Server when not supplied: CL-00001
        b.Property(x => x.CompanyCode)
         .HasMaxLength(20)
         .HasDefaultValueSql("(N'CL-' + FORMAT(NEXT VALUE FOR dbo.Seq_ClientCode, 'D5'))");

        b.Property(x => x.CompanyName).HasMaxLength(200).IsRequired();
        b.Property(x => x.CompanyNameAr).HasMaxLength(200);

        // PERSISTED computed column - never written by EF
        b.Property(x => x.NormalizedName)
         .HasMaxLength(200)
         .HasComputedColumnSql("CAST(UPPER(LTRIM(RTRIM([CompanyName]))) AS NVARCHAR(200))", stored: true);

        b.Property(x => x.Industry).HasMaxLength(100);
        b.Property(x => x.Phone).HasMaxLength(30);
        b.Property(x => x.Email).HasMaxLength(256);
        b.Property(x => x.Website).HasMaxLength(256);
        b.Property(x => x.Address).HasMaxLength(500);
        b.Property(x => x.Country).HasMaxLength(100).IsRequired();
        b.Property(x => x.City).HasMaxLength(100);
        b.Property(x => x.Status).HasConversion<byte>();
        b.Property(x => x.Source).HasConversion<byte>();
        b.Property(x => x.RowVersion).IsRowVersion();

        b.HasOne(x => x.AccountManager)
         .WithMany()
         .HasForeignKey(x => x.AccountManagerId)
         .OnDelete(DeleteBehavior.Restrict);

        b.HasOne(x => x.ImportBatch)
         .WithMany(x => x.Clients)
         .HasForeignKey(x => x.ImportBatchId)
         .OnDelete(DeleteBehavior.Restrict);

        b.HasIndex(x => x.CompanyCode).IsUnique().HasFilter("[IsDeleted] = 0").HasDatabaseName("UX_Clients_CompanyCode");
        b.HasIndex(x => x.NormalizedName).IsUnique().HasFilter("[IsDeleted] = 0").HasDatabaseName("UX_Clients_NormalizedName");
    }
}

public class ClientAssignmentConfiguration : IEntityTypeConfiguration<ClientAssignment>
{
    public void Configure(EntityTypeBuilder<ClientAssignment> b)
    {
        b.ToTable("ClientAssignments");
        b.HasKey(x => new { x.ClientId, x.UserId });

        b.HasOne(x => x.Client)
         .WithMany(x => x.Assignments)
         .HasForeignKey(x => x.ClientId)
         .OnDelete(DeleteBehavior.Cascade);

        b.HasOne(x => x.User)
         .WithMany()
         .HasForeignKey(x => x.UserId)
         .OnDelete(DeleteBehavior.Restrict);
    }
}

public class ContactConfiguration : IEntityTypeConfiguration<Contact>
{
    public void Configure(EntityTypeBuilder<Contact> b)
    {
        b.ToTable("Contacts");
        b.HasKey(x => x.ContactId);

        b.Property(x => x.FullName).HasMaxLength(150).IsRequired();
        b.Property(x => x.JobTitle).HasMaxLength(100);
        b.Property(x => x.Department).HasMaxLength(100);
        b.Property(x => x.Phone).HasMaxLength(30);
        b.Property(x => x.Mobile).HasMaxLength(30);
        b.Property(x => x.Email).HasMaxLength(256);
        b.Property(x => x.RowVersion).IsRowVersion();

        b.HasOne(x => x.Client)
         .WithMany(x => x.Contacts)
         .HasForeignKey(x => x.ClientId)
         .OnDelete(DeleteBehavior.Restrict);

        // Only one primary contact per company
        b.HasIndex(x => x.ClientId)
         .IsUnique()
         .HasFilter("[IsPrimary] = 1 AND [IsDeleted] = 0")
         .HasDatabaseName("UX_Contacts_OnePrimaryPerClient");
    }
}
